    static constexpr int32_t pack(int32_t groupId, int32_t childId) {
        return static_cast<int32_t>((static_cast<uint32_t>(groupId) << 16)
                | (static_cast<uint32_t>(childId) & 0xFFFFu));
    }

    static constexpr int32_t group(int32_t componentId) {
        return static_cast<int32_t>(static_cast<uint32_t>(componentId) >> 16);
    }

    static constexpr int32_t child(int32_t componentId) {
        return componentId & 0xFFFF;
    }

